// The before/after element wraps two togglable views, e.g. before and after images.
// Example:
// <before-after data-load-on="visible">
//  <button data-target="before-after.toggleElement" data-action="change:before-after#toggle">Toggle</button>
//  <div class="position-relative">
//    <img src="url-of-before-image" class="position-absolute top-0 left-0">
//    <img src="url-of-after-image" class="position-absolute top-0 left-0 after-element" data-target="before-after.afterElement">
//  </div>
// </before-after>

import {controller, target, attr} from '@github/catalyst'

@controller('before-after')
class BeforeAfterElement extends HTMLElement {
  @attr toggled = false
  @attr animating = false

  @target declare toggleElement: HTMLElement
  @target declare afterElement: HTMLElement

  #eventAbortController: AbortController | null = null

  connectedCallback() {
    const {signal} = (this.#eventAbortController = new AbortController())

    this.toggle()

    this.afterElement.addEventListener(
      'transitionend',
      () => {
        this.animating = false
      },
      {signal},
    )
  }

  toggle() {
    this.animating = true
    this.toggled = !this.toggled

    this.toggleElement.toggleAttribute('checked', this.toggled)
  }

  disconnectedCallback() {
    this.#eventAbortController?.abort()
  }
}
